def factorial(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

function debounce(fn, delay) {
    let timeout;
    return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => fn.apply(this, args), delay);
    };
}

def fibonacci(n):
    """Return the n-th Fibonacci number (fibonacci(0) == 0, fibonacci(1) == 1)."""
    if n < 0:
        raise ValueError("fibonacci requires a non-negative integer")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def safe_divide(a, b):
    """Divide a by b, returning 0.0 on division by zero."""
    if b == 0:
        return 0.0
    return a / b

def load_config(path):
    """Return a (timeout, retries) tuple from a JSON config file."""
    import json
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    return data.get("timeout"), data.get("retries", 3)

def parse_positive_int(s):
    """Parse s into a positive integer; raise ValueError for invalid input."""
    if not isinstance(s, str) or not s.strip():
        raise ValueError("input must be a non-empty string")
    value = int(s)
    if value <= 0:
        raise ValueError("value must be a positive integer")
    return value
